def min_time(tasks, n):
    if not tasks:
        return 0

    tasks = list(map(int, tasks))
    tasks.sort()
    time = 0
    prev_task = tasks[0]

    for task in tasks[1:]:
        if task - prev_task >= n:
            time += task
            prev_task = task
        else:
            time += n + task
            prev_task = task + n

    return time

