def least_interval(tasks, n):
    if not tasks:
        return 0

    tasks = list(map(int, tasks))
    tasks.sort()
    max_task = max(tasks)
    max_count = tasks.count(max_task)

    if max_count > (len(tasks) - max_count):
        return (max_task + n) * (max_count + 1)
    else:
        return max_task + n + max(tasks)

