def longestSubstringWithSameLetters(s, k):
    if not s or k == 0:
        return 0

    n = len(s)
    max_len = 0

    for i in range(n):
        counts = [0] * 26
        max_count = 0
        for j in range(i, n):
            idx = ord(s[j]) - ord('a')
            counts[idx] += 1
            max_count = max(max_count, counts[idx])

            if max_count <= k:
                max_len = max(max_len, j - i + 1)

    return max_len

