def reorder_packets(packets: List[int], indices: List[int]) -> List[int]:
    # Create a dictionary to store the packets with their indices as keys
    packet_dict = {index: packet for index, packet in zip(indices, packets)}

    # Sort the indices in ascending order
    sorted_indices = sorted(packet_dict.keys())

    # Reorder the packets based on the sorted indices
    reordered_packets = [packet_dict[index] for index in sorted_indices]

    return reordered_packets"}

